  e.kit.frag = 0; h.press(K.throw); assert.equal(e.cooking(), null); assert.match(h.el('notice').textContent, /^NO FRAG LEFT$/); h.release(K.throw); assert.equal(e.nades.length, 0); assert.equal(e.kit.frag, 0);
  // Nothing else can be done with an item in hand: no shot, no reload, no change of weapon.
  e.kit.frag = 1; h.press(K.throw); const ammo = h.weapon.ammo; h.coop.shoot(); h.weapon.ammo--; h.weapon.ammo++; assert.equal(h.weapon.ammo, ammo, 'no shot'); h.press(K.swap); assert.equal(e.slot(), 0); h.weapon.ammo = 5; h.press(K.reload); assert.equal(h.weapon.reloadRemaining, 0); h.weapon.ammo = ammo; h.release(K.throw); assert.equal(e.kit.frag, 0);
  report.fuses = {frag: ITEMS.frag.fuse, smoke: ITEMS.smoke.fuse, flash: ITEMS.flash.fuse};
