  const clearView = watch(3); assert(clearView.seen > .9 && clearView.fired > .5, `in the open the enemy sees and fires (${JSON.stringify(clearView)})`);
  const mid = V(LANE.x, g.groundY(LANE.x, LANE.from - 7), LANE.from - 7); q.throwItem('smoke', mid.clone().setY(mid.y + .2), V(0, -1, 0), 0, true, 'local'); assert.equal(q.smokes.length, 1); watch(ITEMS.smoke.grow + .4);
  const eyeA = a.g.position.clone().setY(a.g.position.y + 1.42), eyeP = g.player.clone().setY(g.player.y + 1.7); assert(!g.visible(eyeA, eyeP) && !g.visible(eyeP, eyeA), 'blocked both ways'); assert(q.clear(eyeA, eyeP), 'no wall is in the way'); assert(!g.visible(mid.clone().setY(mid.y + 1.2), eyeP), 'and from inside the cloud');
  const smoked = watch(6); assert.equal(smoked.seen, 0, 'the enemy does not see the player through smoke'); assert.equal(smoked.fired, 0, 'and does not fire'); assert(g.visible(eyeP, eyeP.clone().add(V(8, 0, 0))), 'a line that misses the cloud is open');
