  const to = P.clone().sub(g.player.clone().setY(g.player.y + 1.7)), base = Math.atan2(-to.x, -to.z); lookAlong(g, base + 60 * Math.PI / 180, 0); q.flashBurst(P); const edge = q.blind(); assert(edge > 0 && edge < playerBlind, `near the edge of the cone: less (${edge.toFixed(2)} s)`); g.run(5); lookAlong(g, base + 80 * Math.PI / 180, 0); q.flashBurst(P); assert.equal(q.blind(), 0, 'outside the cone: not');
  // Smoke between the flash and the eye stops it, for the enemy and the player.
  for (const a of E8) a.blindUntil = 0; stand(g, facing, LANE.x, 3, Math.PI); q.throwItem('smoke', V(LANE.x, g.groundY(LANE.x, 8.5) + .3, 8.5), V(0, -1, 0), 0, true, 'local'); g.run(2.2, () => g.set({hp: 1e9})); q.flashBurst(P); assert.equal(left(facing), 0, 'an enemy behind smoke is not blinded'); q.equipReset(); g.goTo(LANE.x, LANE.from); q.throwItem('smoke', V(LANE.x, g.groundY(LANE.x, 19.5) + .3, 19.5), V(0, -1, 0), 0, true, 'local'); g.run(2.2, () => g.set({hp: 1e9})); lookAt(g, P); q.flashBurst(P); assert.equal(q.blind(), 0, 'nor a player behind smoke');
  // The rule, by numbers.
  const L = {x: 0, y: 0, z: -1}; assert.equal(blindFor(5, L, {x: 0, y: 0, z: -1}), +(4.5 * .8).toFixed(2)); assert.equal(blindFor(5, L, {x: 0, y: 0, z: 1}), 0); assert.equal(blindFor(25, L, L), 0); assert.equal(blindFor(24.9, L, L), ITEMS.flash.least); assert(blindFor(5, L, {x: Math.sin(1.2), y: 0, z: -Math.cos(1.2)}) > 0 && blindFor(5, L, {x: Math.sin(1.4), y: 0, z: -Math.cos(1.4)}) === 0);
