  g.press(K.swap); g.step(40); assert.match(prompt(), /\nYOUR M9 SIDEARM · RESERVE 15\/45 · DRESSINGS 2\/5\nB · MAGAZINE \(15 RDS\) · 30 PTS   N · FIELD DRESSING · 150 PTS\n1 · FRAG/); A.points = side - 1; g.press(K.ammo); assert.equal(q.sidearm.reserve, 15, 'one point short'); A.points = 100; g.press(K.ammo); assert.deepEqual([q.sidearm.reserve, g.weapon.reserve, A.points], [30, 30, 100 - side]); g.press(K.ammo); g.press(K.ammo); assert.equal(q.sidearm.reserve, SIDEARM.reserve, 'up to what the sidearm carries'); const left = A.points; g.press(K.ammo); assert.equal(A.points, left); assert.match(g.el('notice').textContent, /^RESERVE FULL$/);
