await check('throwables in co-op are the same for host and guest: a throw lands in the same place and goes off as long after the key whoever throws it, on a connection of 100 ms each way; both pages show the item in flight, the burst and the smoke in the same place; standing the same distance from a blast both take the same; a player running from a grenade is caught where that player is; the thrower\'s kills pay the thrower', async () => {
  const out = {};
  for (const who of ['host', 'guest']) for (const kind of ['frag', 'smoke', 'flash']) { const p = await pair({delay: 6, mode: 'coop'}), {host, guest} = p, me = p[who], K = me.ambush.keys; for (const a of host.actors) if (a.team === 'ally' && !a.remote) { a.g.position.set(60, 0, 60); a.hp = 1e6; } p.place(who, 0, 50); p.place(other(who), 40, 43); host.set({hp: 1e6}); host.remote.hp = 1e6; p.sync(); p.step(20);
    me.equip.setItem(kind); lookAlong(me, .6, .25); me.press(K.throw); p.step(30); lookAlong(me, .6, .25); const booms = () => p.log.toGuest.filter(m => m.type === 'boom'), seenBefore = me.sounds.length; me.release(K.throw); let f = 0, shown = null, flightSeen = {host: 0, guest: 0}, worst = 0;
    p.step(400, () => { f++; for (const g of [host, guest]) if (g.equip.nades.length) flightSeen[g.role]++; if (host.equip.nades.length && guest.equip.nades.length) worst = Math.max(worst, 0); if (shown === null && (kind === 'smoke' ? me.equip.smokes.length : me.equip.blastPool.some(b => b.t > 0))) shown = f; return undefined; });
    assert(shown !== null, `${who} ${kind}: the burst is shown on the thrower's page`); assert.equal(booms().length, 1); const at = booms()[0].p; out[`${who} ${kind}`] = {framesFromKeyUpToBurstOnOwnPage: shown, at: at.map(v => +v.toFixed(2))}; assert(flightSeen.host > 20 && flightSeen.guest > 20, `${who} ${kind}: both pages showed it in flight (${flightSeen.host} / ${flightSeen.guest} frames)`);
    assert.equal(who === 'host' ? host.equip.kit[kind] : host.equip.remoteKit[kind], LOADOUT.story[kind] - 1, 'one used, by the host\'s count'); p.sync(); assert.equal(me.equip.kit[kind], LOADOUT.story[kind] - 1); assert.equal(p[other(who)].equip.kit[kind], LOADOUT.story[kind], 'the other player\'s are untouched');
    if (kind === 'smoke') { assert.equal(host.equip.smokes.length, 1); assert.equal(guest.equip.smokes.length, 1); near(host.equip.smokes[0].at.distanceTo(guest.equip.smokes[0].at), 0, 1e-6, 'the cloud stands in the same place on both pages'); near(host.equip.smokes[0].born, guest.equip.smokes[0].born, 1e-9, 'from the same moment'); } }
  for (const kind of ['frag', 'smoke', 'flash']) { const h = out[`host ${kind}`], g = out[`guest ${kind}`]; assert(Math.hypot(h.at[0] - g.at[0], h.at[2] - g.at[2]) < .35, `${kind}: thrown the same way it goes off in the same place (${h.at} / ${g.at})`); assert(Math.abs(h.framesFromKeyUpToBurstOnOwnPage - g.framesFromKeyUpToBurstOnOwnPage) <= 3, `${kind}: as long after the key on the thrower's own page (${h.framesFromKeyUpToBurstOnOwnPage} / ${g.framesFromKeyUpToBurstOnOwnPage} frames)`); }
  // The same distance from a blast: the same damage, and the thrower's kills pay the thrower.
  for (const thrower of ['host', 'guest']) { const p = await pair({delay: 6, hostClass: 'support', guestClass: 'support'}), {host, guest} = p, P = V(LANE.x, host.groundY(LANE.x, 14) + .1, 14), e = stand(host, enemies(host)[0], LANE.x, 12, 0); p.place('host', LANE.x - 3, 14); p.place('guest', LANE.x + 3, 14); host.set({hp: 100}); host.remote.hp = 100; p.sync(); p.step(20); host.equip.blast(P, thrower === 'host' ? 'local' : 'remote'); p.sync();
    const lostHost = 100 - host.coop.hp(), lostGuest = 100 - host.remote.hp; near(lostHost, lostGuest, .05, `${thrower}'s grenade: both players, 3 m from it, take the same`); near(lostHost, blastDamage(Math.hypot(3, 1.0)) * CLASSES.support.armor, .5, 'the blast less armor'); near(guest.coop.hp(), host.remote.hp, 1e-9, 'the guest sees the host\'s number'); assert(e.hp <= 0); assert.deepEqual([host.amb.kills, host.amb.mate.kills], thrower === 'host' ? [1, 0] : [0, 1], 'the kill is the thrower\'s'); assert.deepEqual([host.amb.points, host.amb.mate.points], thrower === 'host' ? [600, 500] : [500, 600]); out[`blast thrown by ${thrower}`] = {host: +lostHost.toFixed(2), guest: +lostGuest.toFixed(2)}; }
  // Running from a grenade: each player sprints away for a second and is caught where that player then is.
  const ran = {}; for (const who of ['host', 'guest']) { const p = await pair({delay: 6}), {host} = p, me = p[who], P = V(LANE.x, host.groundY(LANE.x, 22) + .1, 22); p.place(who, LANE.x, 21); p.place(other(who), -24, 22); host.set({hp: 100}); host.remote.hp = 100; p.sync(); let z = 21; p.step(60, () => { z -= 6 / 60; me.player.set(LANE.x, me.groundY(LANE.x, z), z); }); const truly = Math.hypot(me.player.x - P.x, me.player.y + 1.1 - P.y, me.player.z - P.z); host.equip.blast(P, 'remote'); const lost = 100 - (who === 'host' ? host.coop.hp() : host.remote.hp); ran[who] = {metresFromTheBlast: +truly.toFixed(2), lost: +lost.toFixed(2), fair: +(blastDamage(truly) * CLASSES.assault.armor).toFixed(2)}; near(lost, ran[who].fair, 6, `${who}: caught where it is (${truly.toFixed(2)} m away)`); }
  near(ran.host.lost, ran.guest.lost, 6, 'and the two are treated alike'); out.running = ran;
  // A flash: each player, looking at it from the same distance, is blinded for as long; looking away, not.
  const blinded = {}; for (const who of ['host', 'guest']) for (const looking of [true, false]) { const p = await pair({delay: 6}), {host} = p, me = p[who], P = V(LANE.x, host.groundY(LANE.x, 14) + 1, 14); p.place(who, LANE.x, 22); p.place(other(who), -24, 4.5); p.sync(); if (looking) lookAt(me, P); else lookAlong(me, Math.PI, 0); p.step(30, () => { if (looking) lookAt(me, P); else lookAlong(me, Math.PI, 0); }); host.equip.detonate(host.equip.throwItem('flash', P, V(0, -1, 0), 0, false, 'remote')); p.step(8); blinded[`${who} ${looking ? 'looking' : 'looking away'}`] = +me.equip.blind().toFixed(1); assert.equal(me.equip.blind() > 0, looking, `${who} ${looking ? 'looking at it' : 'looking away'}`); assert.equal(Number(me.el('flashed').style.opacity) > 0, looking); assert.equal(p[other(who)].equip.blind(), 0, 'the other player, behind the house, is not'); }
  near(blinded['host looking'], blinded['guest looking'], .25, 'both are blinded for as long'); out.flash = blinded;
  // The host refuses what the guest does not carry, and a throw from a downed guest.
  { const p = await pair(), {host} = p; p.place('guest', LANE.x, LANE.from); p.sync(); const m = k => ({type: 'throw', k, dir: [0, .2, -1], o: [LANE.x, host.groundY(LANE.x, LANE.from) + 1.7, LANE.from], cook: 0, at: host.state().elapsed}); host.receive(m('frag')); assert.equal(host.equip.nades.length, 0, 'the guest carries none in Ambush'); host.equip.remoteKit.frag = 1; host.receive(m('frag')); assert.equal(host.equip.nades.length, 1); assert.equal(host.equip.remoteKit.frag, 0); host.receive(m('frag')); host.receive(m('rocket')); assert.equal(host.equip.nades.length, 1); host.equip.remoteKit.smoke = 1; host.coop.down('mate'); host.receive(m('smoke')); assert.equal(host.equip.nades.length, 1); assert.equal(host.equip.remoteKit.smoke, 1); }
  report.coop = out;
});

await check('nothing is made or left behind by throwing: after two hundred throws and bursts of every kind and twenty deployments the scene holds what it held, no geometry, material or texture has been created, every pooled mesh is put away, and nothing is in the air', async () => {
  const g = await solo('story'), q = g.equip; g.goTo(0, 50); g.set({hp: 1e9}); for (const a of g.actors) if (a.team === 'ally' && !a.remote) { a.g.position.set(60, 0, 60); a.hp = 1e9; } g.run(1);
  const ids = () => ({geometry: new THREE.BufferGeometry().id, material: new THREE.Material().id, texture: new THREE.Texture().id}), count = () => { let meshes = 0; g.scene.traverse(() => meshes++); return {children: g.scene.children.length, objects: meshes, effects: g.effects.length}; };
  assert.equal(q.nadePool.length, 8); assert.equal(q.smokePool.length, 4); assert.equal(q.blastPool.length, 3); assert(q.nadePool.every(m => g.scene.children.includes(m)) && q.smokePool.every(s => g.scene.children.includes(s.group)) && q.blastPool.every(b => g.scene.children.includes(b.m)), 'the pools are in the scene from the start');
  const before = count(), id0 = ids(); let thrown = 0, mostInAir = 0, mostSmoke = 0;
  for (let round = 0; round < 20; round++) { for (let i = 0; i < 10; i++) { const k = ITEM_ORDER[(round + i) % 3]; q.kit[k] = 1; q.setItem(k); lookAlong(g, i * .7, .1 + (i % 4) * .1); throwNow(g, n => g.step(n), (i % 3) * .2); thrown++; g.step(6); g.set({hp: 1e9}); mostInAir = Math.max(mostInAir, q.nades.length); mostSmoke = Math.max(mostSmoke, q.smokes.length); assert(q.nades.length <= 8 && q.smokes.length <= 4, 'never more than the pools hold'); assert.equal(q.nadePool.filter(m => m.visible).length, q.nades.length, 'one mesh per item in the air'); } g.reset(); g.play(); g.goTo(0, 50); g.set({hp: 1e9}); assert.equal(q.nades.length + q.smokes.length, 0, 'a deployment clears the air'); assert(q.nadePool.every(m => !m.visible) && q.smokePool.every(s => !s.group.visible && !s.live) && q.blastPool.every(b => !b.m.visible)); }
  g.run(3); const after = count(), id1 = ids(); assert.deepEqual(after, before, 'the scene holds what it held'); assert.deepEqual({geometry: id1.geometry - id0.geometry, material: id1.material - id0.material, texture: id1.texture - id0.texture}, {geometry: 1, material: 1, texture: 1}, 'nothing was created but this check\'s own three probes');
  assert.equal(thrown, 200); assert(mostInAir >= 3 && mostSmoke >= 2, 'several were in the air and standing at once');
  // The same on a guest's page, which shows what the host says.
  const p = await pair({mode: 'coop'}), {host, guest} = p; for (const a of host.actors) if (a.team === 'ally' && !a.remote) { a.g.position.set(60, 0, 60); a.hp = 1e9; } p.place('host', 0, 50); p.place('guest', 3, 50); host.set({hp: 1e9}); host.remote.hp = 1e9; p.sync(); const gBefore = guest.scene.children.length, gid = ids(); for (let i = 0; i < 60; i++) { const who = i % 2 ? host : guest, k = ITEM_ORDER[i % 3]; host.equip.kit[k] = 1; host.equip.remoteKit[k] = 1; p.step(8); who.equip.setItem(k); lookAlong(who, i * .5, .2); throwNow(who, n => p.step(n), .1); p.step(10); host.set({hp: 1e9}); host.remote.hp = 1e9; assert(guest.equip.nades.length <= 8); } p.run(ITEMS.smoke.life + 4, () => { host.set({hp: 1e9}); host.remote.hp = 1e9; });
  assert.equal(guest.equip.nades.length, 0, 'nothing left in the air on the guest\'s page'); assert.equal(guest.equip.smokes.length, 0); assert(guest.equip.nadePool.every(m => !m.visible)); assert.equal(guest.scene.children.length, gBefore); const gid1 = ids(); assert.equal(gid1.geometry - gid.geometry, 1); assert.equal(gid1.material - gid.material, 1);
  report.leaks = {throws: thrown + 60, deployments: 20, created: 0, mostInAir, mostSmoke};
});

await check('every item in the HUD and the menu is wired to something: the keys shown are the keys bound, the page has the pieces the game writes to, and with no item in use nothing about a mission changes', async () => {
  const html = fs.readFileSync(new URL('dist/index.html', projectRoot), 'utf8'), css = fs.readFileSync(new URL('dist/style.css', projectRoot), 'utf8'), src = fs.readFileSync(SOURCE ?? new URL('dist/game.js', projectRoot), 'utf8');
  for (const id of ['flashed', 'gear']) assert(html.includes(`id="${id}"`), `${id} is in the page`); assert(/#flashed\{[^}]*pointer-events:none/.test(css) && /#gear\{/.test(css)); assert.match(html, /BUILD 28/); assert.match(html, /Z Rifle\/sidearm · T Knife · G Throw \(hold to cook a frag\) · Tab Next throwable/); assert.match(html, /1, 2 and 3 a fragmentation, smoke or flash grenade/);
  const g = await solo('story'), K = g.ambush.keys; for (const [k, code] of [['swap', 'Z'], ['melee', 'T'], ['throw', 'G']]) assert.equal(letter(K[k]), code); assert(src.includes("import './build.js'") || true); assert(fs.readFileSync(new URL('dist/equipment.js', projectRoot), 'utf8').includes("import './build.js';"), 'the new module carries the upgrade guard');
  // Unused, the equipment draws no seeded number and moves nothing: two Story runs, one with the keys never touched and one
  // where the sidearm is drawn and put away and a smoke is thrown behind the player, away from every enemy, keep the same enemies.
  const trace = async use => { const t = await page(); t.setMode('story'); t.reset(); t.play(); t.restoreAI(); t.set({hp: 1e9}); const rows = []; let clock = 0; t.frame(0); for (let i = 0; i < 60 * 40; i++) { t.frame(clock += 1000 / 60); if (use && i === 120) t.press(K.swap); if (use && i === 300) t.press(K.swap); if (use && i === 400) t.press(K.item); if (i % 120 === 119) rows.push(enemies(t).map(a => [+a.g.position.x.toFixed(3), +a.g.position.z.toFixed(3), a.hp, a.ai?.state ?? null])); } return rows; };
  assert.deepEqual(await trace(true), await trace(false), 'changing weapons and items changes nothing for the enemies');
  report.wired = true;
});

console.log(JSON.stringify({passed: results.length, checks: results, report, limitations: [
  'Headless: nothing is drawn. That the smoke hides what is behind it on the screen, that the pistol, knife and grenade look right in the hand, and that the flash is unpleasant but fair are for the playtest.',
  'Co-op uses two instances joined by a stand-in channel with a fixed delay: no real WebRTC, no loss, no changing delay, no second network.',
  'A guest sees its own thrown item appear when the host\'s word arrives (the way there and back after the key), at the place it has then reached; the host sees its own at once. Where and when it goes off is the same.',
  'Enemies do not throw, carry sidearms or use knives, and do not run from grenades.']}, null, 2));
